import itertools
import json

def solve_puzzle():
    # Input variables
    houses = [1, 2]  # House numbers left to right
    Names = ['Eric', 'Arnold']
    Hobbies = ['gardening', 'photography']
    BookGenres = ['science fiction', 'mystery']
    MusicGenres = ['rock', 'pop']
    Birthdays = ['april', 'sept']

    solution_rows = None

    for name_perm in itertools.permutations(Names):
        # Clue 2: Arnold is not in the first house.
        if name_perm[0] == 'Arnold':
            continue

        for book_perm in itertools.permutations(BookGenres):
            # Clue 5: The person who loves mystery books is in the first house.
            if book_perm[0] != 'mystery':
                continue

            for music_perm in itertools.permutations(MusicGenres):
                # Clue 1: mystery <-> rock
                if music_perm[book_perm.index('mystery')] != 'rock':
                    continue

                for hobby_perm in itertools.permutations(Hobbies):
                    # Clue 3: mystery <-> gardening
                    if hobby_perm[book_perm.index('mystery')] != 'gardening':
                        continue

                    for bday_perm in itertools.permutations(Birthdays):
                        # Clue 4: April is Arnold
                        if bday_perm[name_perm.index('Arnold')] != 'april':
                            continue

                        # If all constraints satisfied, build the solution rows
                        rows = []
                        for i, house in enumerate(houses):
                            rows.append([
                                str(house),
                                name_perm[i],
                                hobby_perm[i],
                                book_perm[i],
                                music_perm[i],
                                bday_perm[i]
                            ])
                        solution_rows = rows
                        break
                    if solution_rows:
                        break
                if solution_rows:
                    break
            if solution_rows:
                break
        if solution_rows:
            break

    output = {
        "solution": {
            "header": ["House", "Name", "Hobby", "BookGenre", "MusicGenre", "Birthday"],
            "rows": solution_rows if solution_rows else []
        }
    }
    print(json.dumps(output))

if __name__ == "__main__":
    solve_puzzle()
